conn[coords_,c_,s_,hyper_]:=Module[{w=ConstantArray[0,{4,4,4}]},If[hyper,w[[1,2,2]]=1;w[[1,3,3]]=s;w[[1,4,4]]=s Sin[coords[[3]]]];w[[2,3,3]]=-c;w[[2,4,4]]=-c Sin[coords[[3]]];w[[3,4,4]]=-Cos[coords[[3]]];Do[w[[j,i,k]]=-w[[i,j,k]],{i,1,4},{j,i+1,4},{k,4}];w];
curvature[w_,x_]:=Table[D[w[[i,j,nu]],x[[mu]]]-D[w[[i,j,mu]],x[[nu]]]+Sum[w[[i,k,mu]] w[[k,j,nu]]-w[[i,k,nu]] w[[k,j,mu]],{k,Length[w]}],{i,Length[w]},{j,Length[w]},{mu,Length[x]},{nu,Length[x]}];
torsion[e_,w_,x_]:=Table[D[e[[i,nu]],x[[mu]]]-D[e[[i,mu]],x[[nu]]]+Sum[w[[i,j,mu]] e[[j,nu]]-w[[i,j,nu]] e[[j,mu]],{j,4}],{i,4},{mu,4},{nu,4}];
zeroQ[z_]:=TrueQ[FullSimplify[z==ConstantArray[0,Dimensions[z]],Assumptions->{tau>0,rho>0,0<theta<Pi,rr>0,aa>0,Element[gam,Reals]}]];
