afied[w_]:=Table[-Sum[eps[i,j,k] w[[j+1,k+1,mu]],{j,3},{k,3}]/2+gam w[[1,i+1,mu]],{i,3},{mu,4}];
curvA[A_,x_]:=Table[D[A[[i,nu]],x[[mu]]]-D[A[[i,mu]],x[[nu]]]+Sum[eps[i,j,k] A[[j,mu]] A[[k,nu]],{j,3},{k,3}],{i,3},{mu,Length[x]},{nu,Length[x]}];
