DK=Table[D[Kh[[i,nu]],xh[[mu]]]-D[Kh[[i,mu]],xh[[nu]]]+Sum[eps[i,j,k](Gh[[j,mu]] Kh[[k,nu]]-Gh[[j,nu]] Kh[[k,mu]]),{j,3},{k,3}],{i,3},{mu,4},{nu,4}];metric=Transpose[eh].eta.eh;inverse=Inverse[metric];christ=Table[Sum[inverse[[l,k]](D[metric[[k,j]],xh[[i]]]+D[metric[[k,i]],xh[[j]]]-D[metric[[i,j]],xh[[k]]]),{k,4}]/2,{l,4},{i,4},{j,4}];M=-cc Js[[2]]+gam ss Js[[3]];lam2=cc^2+gam^2 ss^2;
